contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        string memory name_,
        string memory tokenURI,
        bool finiteSupply,
        bool transferable,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance
    ) public payable {
        require(finiteSupply, "test requires finite supply");

        uint256 beforeCount = c.uniqueTokensOutstanding();
        c.createGameItem(
            name_,
            tokenURI,
            finiteSupply,
            transferable,
            itemsRemaining,
            itemPrice,
            dailyAllowance
        );
        uint256 afterCount = c.uniqueTokensOutstanding();
        uint256 newId = afterCount - 1;
        uint256 supply = c.remainingSupply(newId);

        assert(beforeCount == 0 || newId == beforeCount);
        assert(afterCount == beforeCount + 1);
        assert(supply == itemsRemaining);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        string memory name_,
        string memory tokenURI,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance,
        uint256 transferAmount
    ) public payable {
        require(itemsRemaining > 0);
        require(transferAmount > 0);
        require(transferAmount <= itemsRemaining);

        c.createGameItem(
            name_,
            tokenURI,
            true,
            true,
            itemsRemaining,
            itemPrice,
            dailyAllowance
        );

        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        uint256 remainingBefore = c.remainingSupply(tokenId);

        bool reverted;
        try c.safeTransferFrom(address(this), address(0xdead), tokenId, transferAmount, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted || remainingBefore == itemsRemaining || c.balanceOf(address(0xdead), tokenId) == transferAmount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 tokenId, uint256 burnAmount, uint256 mintQuantity, uint256 itemPrice, uint16 dailyAllowance) public {
        require(burnAmount > 0);
        require(mintQuantity >= burnAmount);

        c.createGameItem("TestItem", "uri", false, true, 0, itemPrice, dailyAllowance);

        c.mint(tokenId, mintQuantity);

        uint256 balanceBefore = c.balanceOf(address(this), tokenId);

        c.burn(address(this), tokenId, burnAmount);

        uint256 balanceAfter = c.balanceOf(address(this), tokenId);

        assert(balanceAfter == balanceBefore - burnAmount);
    }

    receive() external payable {}
}

